payload=json.loads(r'''{"revision":"47bcdd428677f6b843807e575b9f3ec56dfd1b1e","files":[{"path":"packages/quds_proofing_harper/tool/build.py","sha":"589015bf0daad5752923c5c8099d97d90ef897df","content":"#!/usr/bin/env python3\n\"\"\"Build and package the optional Harper backend with checked license records.\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport platform\nimport shutil\nimport subprocess\nimport sys\n\nPACKAGE = Path(__file__).resolve().parents[1]\nNATIVE = PACKAGE / \"native\"\n\n\ndef run(args, **kwargs):\n    print(\" \".join(str(arg) for arg in args), flush=True)\n    subprocess.run(args, cwd=NATIVE, check=True, **kwargs)\n\n\ndef source_hashes() -> dict[str, str]:\n    paths = [NATIVE / name for name in (\"Cargo.toml\", \"Cargo.lock\", \"rust-toolchain.toml\")]\n    for directory in (\"native/src\", \"lib\", \"test\", \"web\", \"tool\", \"licenses/upstream\"):\n        paths.extend(path for path in (PACKAGE / directory).rglob(\"*\")\n                     if path.is_file() and \"__pycache__\" not in path.parts)\n    paths.extend((PACKAGE / name) for name in (\"LICENSE\", \"pubspec.yaml\"))\n    return {path.relative_to(PACKAGE).as_posix(): hashlib.sha256(path.read_bytes()).hexdigest()\n            for path in sorted(paths)}\n\n\ndef install(output: Path, kind: str, destination: Path) -> dict:\n    \"\"\"Copy one complete, audited backend into a host's explicit asset location.\"\"\"\n    destination = destination.resolve()\n    if destination == (output / kind).resolve():\n        raise ValueError(\"Choose a host installation directory separate from the build output\")\n    receipt = json.loads((output / \"build-receipt.json\").read_text())\n    artifacts = {name: expected for name, expected in receipt[\"files\"].items()\n                 if name.startswith(kind + \"/\") or name.startswith(\"licenses/\")}\n    # Only ship files named and hashed by the build, never stale build outputs.\n    for name, expected in artifacts.items():\n        if hashlib.sha256((output / name).read_bytes()).hexdigest() != expected:\n            raise ValueError(f\"Changed build artifact: {name}\")\n    destination.mkdir(parents=True, exist_ok=True)\n    for name in artifacts:\n        if not name.startswith(kind + \"/\"): continue\n        shutil.copyfile(output / name, destination / Path(name).name)\n    for name in (\"manifest.json\", \"notices-and-mpl-sources.tar.gz\"):\n        target = destination / \"licenses\" / name\n        target.parent.mkdir(parents=True, exist_ok=True)\n        shutil.copyfile(output / \"licenses\" / name, target)\n    shutil.copyfile(output / \"build-receipt.json\", destination / \"build-receipt.json\")\n    return {\"kind\": kind, \"destination\": str(destination)}\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\"--native\", action=\"store_true\")\n    parser.add_argument(\"--web\", action=\"store_true\")\n    parser.add_argument(\"--output\", type=Path, default=PACKAGE / \"build\")\n    parser.add_argument(\"--install-web\", type=Path, help=\"Copy audited browser files and notices into this host asset directory (requires --web)\")\n    parser.add_argument(\"--install-native\", type=Path, help=\"Copy audited library and notices into this host library directory (requires --native)\")\n    args = parser.parse_args()\n    if not args.native and not args.web: parser.error(\"Select --native, --web, or both\")\n    if args.install_web and not args.web: parser.error(\"--install-web requires --web\")\n    if args.install_native and not args.native: parser.error(\"--install-native requires --native\")\n    output = args.output.resolve()\n    output.mkdir(parents=True, exist_ok=True)\n    before = source_hashes()\n    target_root = Path(os.environ.get(\"CARGO_TARGET_DIR\", NATIVE / \"target\"))\n    if not target_root.is_absolute(): target_root = NATIVE / target_root\n    target_root = target_root.resolve()\n    compiler = subprocess.check_output([\"rustc\", \"--version\", \"--verbose\"], cwd=NATIVE, text=True)\n    host = next(line.split(\": \", 1)[1] for line in compiler.splitlines() if line.startswith(\"host: \"))\n    targets = []\n    binaries = []\n    if args.native:\n        run([\"cargo\", \"build\", \"--release\", \"--locked\"])\n        name = {\"Windows\":\"quds_proofing_harper.dll\", \"Darwin\":\"libquds_proofing_harper.dylib\"}.get(platform.system(), \"libquds_proofing_harper.so\")\n        destination = output / \"native\" / name\n        destination.parent.mkdir(parents=True, exist_ok=True)\n        shutil.copyfile(target_root / \"release\" / name, destination)\n        targets.append(host)\n        binaries.append(destination)\n    if args.web:\n        bindgen = subprocess.check_output([\"wasm-bindgen\", \"--version\"], text=True).strip()\n        if bindgen != \"wasm-bindgen 0.2.130\":\n            raise SystemExit(\"Install the locked glue generator: cargo install wasm-bindgen-cli --version 0.2.130 --locked\")\n        environment = os.environ.copy()\n        environment[\"RUSTFLAGS\"] = environment.get(\"RUSTFLAGS\", \"\") + ' --cfg getrandom_backend=\"wasm_js\"'\n        run([\"cargo\", \"build\", \"--release\", \"--locked\", \"--target\", \"wasm32-unknown-unknown\"], env=environment)\n        web = output / \"web\"\n        web.mkdir(parents=True, exist_ok=True)\n        run([\"wasm-bindgen\", str(target_root / \"wasm32-unknown-unknown\" / \"release\" / \"quds_proofing_harper.wasm\"),\n             \"--target\", \"web\", \"--out-dir\", str(web), \"--out-name\", \"quds_proofing_harper\"])\n        shutil.copyfile(PACKAGE / \"web\" / \"harper_worker.mjs\", web / \"harper_worker.mjs\")\n        targets.append(\"wasm32-unknown-unknown\")\n        binaries.extend([web / \"quds_proofing_harper_bg.wasm\", web / \"quds_proofing_harper.js\", web / \"harper_worker.mjs\"])\n    license_command = [sys.executable, str(PACKAGE / \"tool\" / \"license_bundle.py\"), \"--output\", str(output / \"licenses\")]\n    for target in targets: license_command.extend([\"--target\", target])\n    run(license_command)\n    after = source_hashes()\n    if before != after:\n        raise ValueError(\"Build source changed while commands were running; rebuild before distributing\")\n    receipts = [output / \"licenses\" / name for name in (\"manifest.json\", \"notices-and-mpl-sources.tar.gz\")]\n    receipt = {\"schema_version\": 2, \"compiler\": compiler, \"targets\": targets,\n        \"harper_version\": \"3.2.0\", \"harper_commit\": \"ea9ab1b8f95be99a5d4040c53be92a6c2ad7f7f3\",\n        \"cargo_lock_sha256\": hashlib.sha256((NATIVE / \"Cargo.lock\").read_bytes()).hexdigest(),\n        \"source_sha256\": before, \"source_unchanged_during_build\": True,\n        \"files\": {path.relative_to(output).as_posix(): hashlib.sha256(path.read_bytes()).hexdigest() for path in binaries + receipts}}\n    (output / \"build-receipt.json\").write_text(json.dumps(receipt, indent=2) + \"\\n\")\n    installed = []\n    if args.install_web: installed.append(install(output, \"web\", args.install_web))\n    if args.install_native: installed.append(install(output, \"native\", args.install_native))\n    print(json.dumps({\"status\": \"passed\", \"output\": str(output), \"installed\": installed}))\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"packages/quds_proofing_harper/tool/license_bundle.py","sha":"6381e803a88c79d7c344506d828ce4ce0938daf0","content":"#!/usr/bin/env python3\n\"\"\"Audit actual active Cargo dependencies and preserve their original notices.\n\nInvoke for every shipped target. The resulting directory must accompany the\nbinary/Wasm distribution. MPL source archives are included, with Cargo checksums.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport io\nimport json\nimport os\nfrom pathlib import Path\nimport re\nimport subprocess\nimport tarfile\nimport tomllib\nimport urllib.request\n\nPACKAGE = Path(__file__).resolve().parents[1]\nMANIFEST = PACKAGE / \"native\" / \"Cargo.toml\"\nALLOWED = {\n    \"MIT\", \"Apache-2.0\", \"BSD-2-Clause\", \"BSD-3-Clause\", \"0BSD\", \"MPL-2.0\",\n    \"Unicode-3.0\", \"ISC\", \"Zlib\", \"CC0-1.0\",\n}\nANCILLARY = {\n    \"Unicode-3.0\": \"Permissive Unicode data/code; preserve copyright and permission notices; no endorsement.\",\n    \"ISC\": \"Permissive ancillary code; preserve copyright and permission notice.\",\n    \"Zlib\": \"Permissive ancillary code; preserve notice and accurately identify unmodified source.\",\n    \"CC0-1.0\": \"Public-domain dedication with permissive fallback; preserve the supplied legal text and provenance.\",\n}\n\n\ndef sha256(data: bytes) -> str:\n    return hashlib.sha256(data).hexdigest()\n\n\ndef fallback_notices(name: str) -> list[dict]:\n    prefix = \"HARPER\" if name.startswith(\"harper-\") else \"BURN\" if name.startswith(\"burn-\") else \"CUBECL\" if name == \"cubecl-quant\" else \"EMBASSY\"\n    rows = json.loads((PACKAGE / \"licenses\" / \"upstream\" / \"fallback-notices.json\").read_text())\n    return [item for item in rows if item[\"file\"].startswith(prefix + \"-\")]\n\n\ndef validate_fallback_revision(name: str, source: Path) -> None:\n    \"\"\"A lockfile update must not silently reuse a different revision's notice.\"\"\"\n    vcs = json.loads((source / \".cargo_vcs_info.json\").read_text())\n    revision = vcs.get(\"git\", {}).get(\"sha1\")\n    rows = fallback_notices(name)\n    if not revision or not rows or any(f\"/{revision}/\" not in item[\"url\"] for item in rows):\n        raise ValueError(f\"Review original notices for changed source revision: {name}\")\n\n\ndef selection(expression: str) -> list[str]:\n    \"\"\"SPDX AND/OR/parentheses parser; never mistakes OR for an obligation to both.\"\"\"\n    if not expression:\n        raise ValueError(\"Missing license expression\")\n    expression = expression.replace(\"/\", \" OR \")\n    tokens = re.findall(r\"\\(|\\)|[A-Za-z0-9.+-]+\", expression)\n    if \"\".join(tokens) != re.sub(r\"\\s\", \"\", expression):\n        raise ValueError(f\"Unrecognized license expression: {expression}\")\n    index = 0\n\n    def primary():\n        nonlocal index\n        if index >= len(tokens):\n            raise ValueError(\"Incomplete license expression\")\n        token = tokens[index]\n        index += 1\n        if token == \"(\":\n            value = either()\n            if index >= len(tokens) or tokens[index] != \")\":\n                raise ValueError(\"Unbalanced license expression\")\n            index += 1\n            return value\n        if index < len(tokens) and tokens[index] == \"WITH\":\n            index += 1\n            if index >= len(tokens): raise ValueError(\"Missing license exception\")\n            token += \" WITH \" + tokens[index]\n            index += 1\n        return {token} if token in ALLOWED else None\n\n    def both():\n        nonlocal index\n        value = primary()\n        while index < len(tokens) and tokens[index] == \"AND\":\n            index += 1\n            next_value = primary()\n            value = value | next_value if value is not None and next_value is not None else None\n        return value\n\n    def either():\n        nonlocal index\n        values = [both()]\n        while index < len(tokens) and tokens[index] == \"OR\":\n            index += 1\n            values.append(both())\n        accepted = [value for value in values if value is not None]\n        return min(accepted, key=lambda v: (\"MIT\" not in v, \"Apache-2.0\" not in v, len(v), sorted(v))) if accepted else None\n\n    selected = either()\n    if index != len(tokens) or selected is None:\n        raise ValueError(f\"No allowed license branch in: {expression}\")\n    return sorted(selected)\n\n\ndef cargo(*args: str) -> str:\n    return subprocess.check_output([\"cargo\", *args, \"--manifest-path\", str(MANIFEST), \"--locked\"], cwd=MANIFEST.parent, text=True)\n\n\ndef active_packages(target: str) -> tuple[dict, set[tuple[str, str]]]:\n    metadata = json.loads(cargo(\"metadata\", \"--format-version=1\", \"--filter-platform\", target))\n    tree = cargo(\"tree\", \"--target\", target, \"--edges\", \"normal,build\", \"--prefix\", \"none\", \"--format\", \"{p}\")\n    identities = set()\n    for line in tree.splitlines():\n        match = re.match(r\"^([\\w-]+) v([\\w.+-]+)\", line)\n        if not match:\n            raise ValueError(f\"Unexpected Cargo tree output: {line}\")\n        identities.add(match.groups())\n    return metadata, identities\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\"--target\", action=\"append\", required=True)\n    parser.add_argument(\"--output\", type=Path, required=True)\n    args = parser.parse_args()\n    output = args.output.resolve()\n    output.mkdir(parents=True, exist_ok=True)\n    packages = {}\n    for target in args.target:\n        metadata, active = active_packages(target)\n        for package in metadata[\"packages\"]:\n            key = (package[\"name\"], package[\"version\"])\n            if key in active:\n                packages.setdefault(key, {\"package\": package, \"targets\": []})[\"targets\"].append(target)\n    lock_bytes = MANIFEST.with_name(\"Cargo.lock\").read_bytes()\n    lock = tomllib.loads(lock_bytes.decode())\n    checksums = {(p[\"name\"], p[\"version\"]): p.get(\"checksum\") for p in lock[\"package\"]}\n    records = []\n    archive_files: dict[str, bytes] = {}\n    missing_notices = []\n    for key, entry in sorted(packages.items()):\n        package = entry[\"package\"]\n        name, version = key\n        selected = selection(package[\"license\"])\n        source = Path(package[\"manifest_path\"]).parent\n        vcs_path = source / \".cargo_vcs_info.json\"\n        vcs = json.loads(vcs_path.read_text()) if vcs_path.is_file() else None\n        revision = vcs.get(\"git\", {}).get(\"sha1\") if vcs else None\n        notices = []\n        # Actual files, including subdirectory notices, remain byte-for-byte.\n        for path in sorted(source.rglob(\"*\")):\n            if path.is_file() and path.name.lower().startswith((\"license\", \"licence\", \"copying\", \"copyright\", \"notice\")):\n                if \"target\" in path.relative_to(source).parts or \"build\" in path.relative_to(source).parts: continue\n                content = path.read_bytes()\n                relative = path.relative_to(source).as_posix()\n                destination = f\"notices/{name}-{version}/{relative}\"\n                archive_files[destination] = content\n                notices.append({\"file\": destination, \"sha256\": sha256(content)})\n        if not notices and name in {\"harper-core\", \"harper-brill\", \"harper-pos-utils\", \"burn-ir\", \"burn-nn\", \"burn-optim\", \"cubecl-quant\", \"embassy-futures\"}:\n            validate_fallback_revision(name, source)\n            for item in fallback_notices(name):\n                content = (PACKAGE / \"licenses\" / \"upstream\" / item[\"file\"]).read_bytes()\n                if sha256(content) != item[\"sha256\"]: raise ValueError(\"Changed upstream notice\")\n                destination = f\"notices/{name}-{version}/{item['file']}\"\n                archive_files[destination] = content\n                notices.append({\"file\": destination, \"sha256\": sha256(content), \"source\": item[\"url\"]})\n        if not notices and name == \"quds_proofing_harper\":\n            content = (PACKAGE / \"LICENSE\").read_bytes()\n            destination = f\"notices/{name}-{version}/LICENSE\"\n            archive_files[destination] = content\n            notices.append({\"file\": destination, \"sha256\": sha256(content)})\n        if not notices:\n            missing_notices.append(f\"{name}-{version}\")\n        record = {\"name\": name, \"version\": version, \"declared_license\": package[\"license\"],\n                  \"selected_licenses\": selected, \"source\": package[\"source\"], \"repository\": package[\"repository\"],\n                  \"source_revision\": revision,\n                  \"crate_sha256\": checksums.get(key), \"targets\": sorted(entry[\"targets\"]), \"notices\": notices}\n        if \"MPL-2.0\" in selected:\n            url = f\"https://static.crates.io/crates/{name}/{name}-{version}.crate\"\n            cache = Path(os.environ.get(\"CARGO_HOME\", Path.home() / \".cargo\")) / \"registry\" / \"cache\"\n            matches = list(cache.glob(f\"*/{name}-{version}.crate\"))\n            content = matches[0].read_bytes() if matches else urllib.request.urlopen(url, timeout=60).read()\n            if sha256(content) != checksums[key]: raise ValueError(f\"Changed MPL source archive: {name}\")\n            destination = f\"sources/{name}-{version}.crate\"\n            archive_files[destination] = content\n            record[\"mpl_source\"] = {\"file\": destination, \"sha256\": sha256(content), \"url\": url,\n                \"modified\": False}\n        records.append(record)\n    if missing_notices:\n        raise SystemExit(\"Original notice files missing; review before redistribution: \" + \", \".join(missing_notices))\n    readme = (\n        \"Quds optional Harper distribution: original third-party notices and MPL source\\n\\n\"\n        \"The manifest selects permissive licenses or MPL-2.0 from each SPDX expression.\\n\"\n        \"For MPL components, the exact unmodified source .crate archives are in sources/.\\n\"\n        \"These archives correspond to the checksummed Cargo.lock inputs used for the build.\\n\"\n        \"Keep this bundle and manifest with every redistributed native or Wasm binary.\\n\"\n        \"No GPL/AGPL/LGPL-only dependency is permitted by this audited selection.\\n\"\n    ).encode()\n    archive_files[\"README.txt\"] = readme\n    import gzip\n    with (output / \"notices-and-mpl-sources.tar.gz\").open(\"wb\") as destination:\n        with gzip.GzipFile(fileobj=destination, mode=\"wb\", mtime=0, filename=\"\") as zipped:\n            with tarfile.open(fileobj=zipped, mode=\"w\") as archive:\n                for filename, content in sorted(archive_files.items()):\n                    info = tarfile.TarInfo(filename)\n                    info.size = len(content)\n                    info.mode = 0o644\n                    archive.addfile(info, io.BytesIO(content))\n    result = {\"schema_version\": 1, \"policy\": \"permissive or MPL-2.0; no GPL/AGPL/LGPL-only components\",\n              \"reviewed_ancillary_licenses\": ANCILLARY, \"targets\": sorted(args.target),\n              \"cargo_lock_sha256\": sha256(lock_bytes), \"package_count\": len(records),\n              \"notice_bundle_sha256\": sha256((output / \"notices-and-mpl-sources.tar.gz\").read_bytes()),\n              \"packages\": records}\n    (output / \"manifest.json\").write_text(json.dumps(result, indent=2) + \"\\n\")\n    print(json.dumps({\"packages\": len(records), \"output\": str(output), \"status\": \"passed\"}))\n\n\nif __name__ == \"__main__\":\n    main()\n"},{"path":"packages/quds_proofing_harper/tool/test_build_packaging.py","sha":"c4d80dee196203a71511447405aa617c30830b86","content":"\"\"\"Host packages must contain the audited runtime, not stale generated files.\"\"\"\nimport hashlib\nimport json\nfrom pathlib import Path\nimport tempfile\nimport unittest\n\nfrom build import install\n\n\nclass HostPackagingTest(unittest.TestCase):\n    def make_distribution(self, root):\n        output = root / \"build\"\n        names = [\"web/harper_worker.mjs\", \"web/quds_proofing_harper.js\",\n                 \"web/quds_proofing_harper_bg.wasm\", \"licenses/manifest.json\",\n                 \"licenses/notices-and-mpl-sources.tar.gz\"]\n        hashes = {}\n        for name in names:\n            path = output / name\n            path.parent.mkdir(parents=True, exist_ok=True)\n            path.write_bytes(name.encode())\n            hashes[name] = hashlib.sha256(path.read_bytes()).hexdigest()\n        (output / \"build-receipt.json\").write_text(json.dumps({\"files\": hashes}))\n        return output\n\n    def test_only_audited_runtime_and_notices_are_installed(self):\n        with tempfile.TemporaryDirectory() as temporary:\n            root = Path(temporary)\n            output = self.make_distribution(root)\n            (output / \"web\" / \"stale-worker.mjs\").write_text(\"stale\")\n            (output / \"web\" / \"quds_proofing_harper.d.ts\").write_text(\"types\")\n            destination = root / \"host\"\n            install(output, \"web\", destination)\n            self.assertEqual(\n                {path.relative_to(destination).as_posix()\n                 for path in destination.rglob(\"*\") if path.is_file()},\n                {\"harper_worker.mjs\", \"quds_proofing_harper.js\",\n                 \"quds_proofing_harper_bg.wasm\", \"build-receipt.json\",\n                 \"licenses/manifest.json\", \"licenses/notices-and-mpl-sources.tar.gz\"},\n            )\n            self.assertEqual((destination / \"harper_worker.mjs\").read_bytes(),\n                             (output / \"web\" / \"harper_worker.mjs\").read_bytes())\n\n    def test_changed_runtime_or_notices_fail_before_host_writes(self):\n        for changed in (\"web/harper_worker.mjs\", \"licenses/notices-and-mpl-sources.tar.gz\"):\n            with self.subTest(changed=changed), tempfile.TemporaryDirectory() as temporary:\n                root = Path(temporary)\n                output = self.make_distribution(root)\n                (output / changed).write_bytes(b\"changed after build\")\n                destination = root / \"host\"\n                with self.assertRaisesRegex(ValueError, \"Changed build artifact\"):\n                    install(output, \"web\", destination)\n                self.assertFalse(destination.exists())\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"},{"path":"packages/quds_proofing_harper/tool/test_license_bundle.py","sha":"c8ad4082aa9ec3e75de28b25dcb5e5803f6c6a64","content":"\"\"\"Regression controls for the distribution license gate.\"\"\"\nimport json\nfrom pathlib import Path\nimport tempfile\nimport unittest\n\nfrom license_bundle import selection, validate_fallback_revision\n\n\nclass LicensePolicyTest(unittest.TestCase):\n    def test_selects_permitted_alternative(self):\n        for expression, expected in [\n            (\"MIT OR Apache-2.0\", [\"MIT\"]),\n            (\"GPL-2.0-only OR MPL-2.0\", [\"MPL-2.0\"]),\n            (\"(MIT OR GPL-3.0-only) AND BSD-3-Clause\", [\"BSD-3-Clause\", \"MIT\"]),\n            (\"Apache-2.0/MIT\", [\"MIT\"]),\n            (\"Unicode-3.0\", [\"Unicode-3.0\"]),\n        ]:\n            with self.subTest(expression=expression):\n                self.assertEqual(selection(expression), expected)\n\n    def test_rejects_forbidden_unknown_and_malformed_terms(self):\n        for expression in [\n            \"GPL-3.0-only\", \"LGPL-2.1-only\", \"AGPL-3.0-only\",\n            \"MIT AND GPL-3.0-only\", \"Unknown-License\", \"\",\n            \"MIT OR\", \"(MIT\", \"MIT WITH\", \"MIT WITH unknown-exception\",\n            \"MIT) OR GPL-3.0-only\", \"MIT; Apache-2.0\",\n        ]:\n            with self.subTest(expression=expression):\n                with self.assertRaises(ValueError):\n                    selection(expression)\n\n    def test_rejects_stale_fallback_notice(self):\n        with tempfile.TemporaryDirectory() as directory:\n            source = Path(directory)\n            (source / \".cargo_vcs_info.json\").write_text(json.dumps({\n                \"git\": {\"sha1\": \"different-source-revision\"},\n            }))\n            with self.assertRaisesRegex(ValueError, \"changed source revision\"):\n                validate_fallback_revision(\"harper-core\", source)\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"},{"path":"packages/quds_proofing_harper/licenses/upstream/fallback-